  'Sales': { fa: 'فروش', ar: 'المبيعات', ru: 'Продажи', es: 'Ventas' },
  'Order number, items, total, and payment method': { fa: 'شمارهٔ سفارش، اقلام، جمع و روش پرداخت', ar: 'رقم الطلب والأصناف والإجمالي وطريقة الدفع', ru: 'Номер заказа, позиции, сумма и способ оплаты', es: 'Número de pedido, productos, total y forma de pago' },
