  'Who, how long, and the wage for the shift': { fa: 'چه کسی، چه مدت، و دستمزد شیفت', ar: 'مَن، وكم المدة، وأجر المناوبة', ru: 'Кто, сколько и оплата за смену', es: 'Quién, cuánto tiempo y el sueldo del turno' },
  'Checklist completed': { fa: 'چک‌لیست تکمیل شد', ar: 'اكتمال قائمة المهام', ru: 'Чек-лист выполнен', es: 'Checklist completado' },
  'Task, priority, category, and assignee': { fa: 'کار، اولویت، دسته و مسئول', ar: 'المهمة والأولوية والفئة والمكلَّف', ru: 'Задача, приоритет, категория и исполнитель', es: 'Tarea, prioridad, categoría y responsable' },
  'Daily summary at midnight': { fa: 'خلاصهٔ روزانه در نیمه‌شب', ar: 'ملخص يومي عند منتصف الليل', ru: 'Сводка за день в полночь', es: 'Resumen diario a medianoche' },
  'Yesterday’s revenue, expenses, profit, payment mix and top sellers': { fa: 'درآمد، هزینه، سود، ترکیب پرداخت و پرفروش‌های دیروز', ar: 'إيرادات الأمس ومصاريفه وأرباحه وتوزيع الدفع والأكثر مبيعًا', ru: 'Вчерашняя выручка, расходы, прибыль, способы оплаты и хиты продаж', es: 'Ingresos, gastos, beneficio, formas de pago y lo más vendido de ayer' },
